css:
/* =========================================================
   Vehicle Inspection Print (A4) — Single Page Guaranteed
   - One page canvas (no page 2)
   - Footer pinned (signatures + footer text)
   - Body clipped so table never pushes page
   - Bilingual headings centered: EN left / AR right
========================================================= */
@import url('https://fonts.googleapis.com/css2?family=Almarai:wght@300;400;700;800&family=Amiri+Quran&family=Amiri:ital,wght@0,400;0,700;1,400;1,700&family=Aref+Ruqaa+Ink:wght@400;700&family=Aref+Ruqaa:wght@400;700&family=Baloo+Bhaijaan+2:wght@400..800&family=Cairo+Play:wght@200..1000&family=Cairo:wght@200..1000&family=Cascadia+Code:ital,wght@0,200..700;1,200..700&family=Cascadia+Mono:ital,wght@0,200..700;1,200..700&family=IBM+Plex+Sans+Arabic:wght@100;200;300;400;500;600;700&family=Lateef:wght@200;300;400;500;600;700;800&family=Lemonada:wght@300..700&family=Noto+Kufi+Arabic:wght@100..900&family=Noto+Naskh+Arabic:wght@400..700&family=Noto+Sans+Arabic:wght@100..900&family=Rubik:ital,wght@0,300..900;1,300..900&family=Scheherazade+New:wght@400;500;600;700&family=Tajawal:wght@200;300;400;500;700;800;900&family=Ubuntu:ital,wght@0,300;0,400;0,500;0,700;1,300;1,400;1,500;1,700&family=Vazirmatn:wght@100..900&family=Zain:ital,wght@0,200;0,300;0,400;0,700;0,800;0,900;1,300;1,400&display=swap');
@page { size: A4; margin: 8mm 8mm 8mm 8mm; }
/* =========================
   A4 + BASE (START)
   Put this block right after @import and @page
========================= */

.page{
  position: relative;
  height: 277mm;              /* one-page canvas inside margins */
  overflow: hidden;           /* never spill to page 2 */
  page-break-inside: avoid;
}

.page-body{
  /* footer reserved area (signatures + footer line) */
  padding-bottom: 58mm;
  height: calc(277mm - 58mm);
  overflow: hidden;
}

.page-footer{
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
}

/* Base typography (keep simple, you can change fonts later) */
body { font-family: Arial, sans-serif; font-size: 11px; color:#111; margin: 0; }
.ar { direction: rtl; text-align: right; }
.en { direction: ltr; text-align: left; }
.small { font-size:10px; color:#333; }

.print-heading, .print-format-meta, .visible-xs { display: none !important; }

/* Center bilingual row (EN left, AR right) */
.bi-row{
  width: 100%;
  max-width: 520px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
}
.bi-row .en{ font-weight: 900; }
.bi-row .ar{ font-weight: 900; }
/* =========================
   HEADER (clean, separated from body)
========================= */
.header-section{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;

  padding: 6px 0 10px 0;
  margin: 0 0 10px 0;
  border-bottom: 2px solid #e9e9e9;
}

.logo-container{
  width: 88px;
  flex: 0 0 88px;
}

.logo-container.spacer{
  visibility: hidden; /* keeps center aligned */
}

.logo{
  max-width: 88px;
  max-height: 46px;
  object-fit: contain;
  display:block;
}

.company-names{
  flex:1;
  text-align: Center;
  line-height: 1.50;
  /*font-family: */
  /*  'Cascadia Mono',*/
  /*  'IBM Plex Sans Arabic',*/
  /*  'Cairo',*/
  /*  'Roboto',*/
  /*  monospace,*/
  /*  sans-serif;*/

}

/* EN */
.company-names .en{
  margin:0;
  font-family:'Roboto', sans-serif;
  font-size:15px;
  font-weight:500;
  color:#000;
  text-align: right;
}

/* AR */
.company-names .ar{
  margin:0;
  font-size:22px;
  font-family: "IBM Plex Sans Arabic", "Cairo", "Tajawal", sans-serif;
  font-weight: 400;
  color:#000;
  direction:rtl;
}

/* =========================
   META LINE (compact, centered)
========================= */
.meta{
  display:flex;
  justify-content:center;
  align-items:baseline;
  gap:18px;
  flex-wrap:wrap;

  padding: 6px 0 8px 0;
  margin: 0 0 10px 0;
  border-bottom:1px solid #f0f0f0;
}

.meta .it{
  display:flex;
  gap:6px;
  align-items:baseline;
  white-space: nowrap;
}

.meta .k{
  font-weight:700;
  color:#111;
}

.meta .v{
  font-weight:700;
  color:#222;
}

/* optional: make values slightly darker */
.meta .v{ color:#000; }
/* =========================
   SECTIONS + CHECKLIST TABLE
========================= */
.sec{
  margin-top: 8px;
  page-break-inside: avoid;
}

.sec-h{
  margin: 0 0 4px 0;
}

table.tbl{
  width:100%;
  border-collapse:collapse;
  table-layout:fixed;
}

table.tbl th{
  font-weight:900;
  font-size:10.5px;
  color:#333;
  border-bottom:1px solid #eaeaea;
  padding:2px 6px;
}

table.tbl td{
  border-bottom:1px solid #f1f1f1;
  padding:3px 6px;
  line-height:.50;
  vertical-align:top;
  word-wrap:break-word;
}
table.tbl tr:last-child td{ border-bottom:0; }

/* column widths (A4 friendly) */
.col-item  { width:50%; }
.col-yes   { width:12%;  text-align:center; font-weight:900; }
.col-no    { width:12%;  text-align:center; font-weight:900; }
.col-notes { width:26%; }

/* stop notes from expanding page height */
.col-notes{
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* compact bilingual header inside table cells */
.th-bi{
  display:block;
  line-height: 1.05;
  text-align:center;
}

.th-bi .en{
  display:block;
  font-weight:900;
  font-size:10.2px;
  margin:0;
}

.th-bi .ar{
  display:block;
  font-weight:900;
  font-size:10.6px;
  margin:0;
  direction:rtl;
}

/* =========================
   SIGNATURES (footer pinned)
========================= */
.sign-row{
  display:flex;
  gap:8px;
  margin-top:6px;
  page-break-inside: avoid;
}

.sign-box{
  flex:1;
  border:1px solid #eaeaea;
  border-radius:8px;
  padding:8px 10px;
  height: 140px;          /* keep compact for A4 */
  position:relative;
  overflow:hidden;
}

/* watermark stamp (does NOT affect layout) */
.wm{
  position:absolute;
  inset:0;
  z-index:0;
  pointer-events:none;
}
.wm img{
  position:absolute;
  top:38%;
  left:38%;
  transform: translate(-50%, -36%) rotate(-8deg);
  width: 100%;
  max-height: 200%;
  opacity: .80;          /* watermark opacity */
  filter: grayscale(100%);
}

/* content above watermark */
.sign-content{
  position:relative;
  z-index:2;
  height:100%;
  display:flex;
  flex-direction:column;
}

.sign-head{ margin-bottom:6px; }

.sign-img{
  flex:1;
  min-height: 100px;
  display:flex;
  align-items:flex-start;
}

.sign-img img{
  max-width:100%;
  max-height: 100px;
  object-fit:contain;
  display:block;
}

.sign-line{ border-top:1px solid #999; margin-top:6px; }
.sign-name{ font-size:10px; font-weight:800; color:#333; margin-top:4px; }

/* =========================
   FOOTER (phone/reg)
========================= */
.ftr{
  margin-top:6px;
  padding-top:6px;
  border-top:1px solid #eee;
  font-size:10px;
  color:#333;
  display:flex;
  justify-content:space-between;
  gap:10px;
}

html:
{# ============================================================
  Vehicle Inspection (A4) — Professional Print Layout (Fixed)
  - Stamp watermark never changes height
  - Bilingual headings: EN left, AR right, block centered
============================================================ #}

{# ---------- Resolve Staff + Company ---------- #}
{% set staff_name = doc.staff or doc.driver or doc.employee or "" %}
{% set staff_company_name =
  doc.company
  or (frappe.db.get_value("Staff", staff_name, "company_name") if staff_name else "")
  or ""
%}

{# ---------- Company meta ---------- #}
{% set company_logo  = frappe.db.get_value("Company", staff_company_name, "company_logo") or "" %}
{% set company_en    = frappe.db.get_value("Company", staff_company_name, "company_name") or "" %}
{% set company_ar    = frappe.db.get_value("Company", staff_company_name, "company_name_arabic") or "" %}
{% set phone_no      = frappe.db.get_value("Company", staff_company_name, "phone_no") or "" %}
{% set reg_no        = frappe.db.get_value("Company", staff_company_name, "registration_details") or "" %}

{# ---------- Helpers ---------- #}
{% macro tick(is_on) -%}{% if is_on %}✓{% else %}&nbsp;{% endif %}{%- endmacro %}
{% macro yn_cols(status) -%}
  {% set st = (status or "") %}
  <td class="col-yes">{{ tick("Unsound" not in st) }}</td>
  <td class="col-no">{{ tick("Unsound" in st) }}</td>
{%- endmacro %}

{# ---------- Group items by section ---------- #}
{% set groups = {} %}
{% for r in (doc.items or []) %}
  {% set sec = (r.section or r.category or "Checklist") %}
  {% if sec not in groups %}{% set _ = groups.update({sec: []}) %}{% endif %}
  {% set _ = groups[sec].append(r) %}
{% endfor %}

<div class="page">
  <div class="page-body">
      <header class="header-section">
  <div class="logo-container">
    {% if company_logo %}
      <img class="logo" src="{{ company_logo }}" alt="Company Logo">
    {% endif %}
  </div>

  <div class="company-names">
    <p class="en">{{ company_en }}</p>
    <p class="ar">{{ company_ar }}</p>

  </div>

  <div class="logo-container spacer"></div>
</header>
<div class="meta">
  {% if doc.inspection_date %}
    <div class="it">
      <span class="k">Date</span>
      <span class="v">{{ doc.inspection_date }}</span>
    </div>
  {% endif %}

  {% if doc.driver %}
    <div class="it">
      <span class="k">Driver</span>
      <span class="v">{{ doc.driver }}</span>
    </div>
  {% endif %}

  {% if doc.vehicle %}
    <div class="it">
      <span class="k">Vehicle</span>
      <span class="v">{{ doc.vehicle }}</span>
    </div>
  {% endif %}
</div>
{# ===================== CHECKLIST SECTIONS ===================== #}
{% for sec, rows in groups.items() %}
  {% if rows and rows|length > 0 %}
    <div class="sec">
      {% if "Dashboard" in sec or "Indicators" in sec %}
        {% set sec_ar = "مؤشرات لوحة القيادة" %}
        {% set sec_en = "Indicators Dashboard" %}
      {% elif "External" in sec %}
        {% set sec_ar = "فحص الأجزاء الخارجية" %}
        {% set sec_en = "External Inspection" %}
      {% elif "Safety" in sec or "Security" in sec %}
        {% set sec_ar = "أدوات ومتطلبات السلامة" %}
        {% set sec_en = "Safety & Security Tools" %}
      {% else %}
        {% set sec_ar = "" %}
        {% set sec_en = sec %}
      {% endif %}

      <div class="sec-h">
        <div class="bi-row">
          <div class="en">{{ sec_en }}</div>
          <div class="ar">{{ sec_ar }}</div>
        </div>
      </div>

      <table class="tbl">
        <thead>
          <tr>
            <th class="col-item">
              <span class="th-bi">
                <span class="en">Item</span>
                <span class="ar">البند</span>
              </span>
            </th>
            <th class="col-yes">
                 <span class="th-bi">
                    <span class="en">Sound</span>
                    <span class="ar">سليم</span>
                  </span>

            </th>
            <th class="col-no">
              <span class="th-bi">
                <span class="en">Unsound</span>
                <span class="ar">غير سليم</span>
              </span>
            </th>
            <th class="col-notes">
            <span class="th-bi">
                <span class="en">Notes</span>
                <span class="ar">ملاحظات</span>
              </span>
            </th>
          </tr>
        </thead>

        <tbody>
          {% for r in rows %}
            <tr>
              <td class="col-item">{{ r.item or "" }}</td>
              {{ yn_cols(r.status) }}
              <td class="col-notes">{{ r.notes or "" }}</td>
            </tr>
          {% endfor %}
        </tbody>
      </table>
    </div>
  {% endif %}
{% endfor %}
    <!-- (NEXT STEP) HEADER GOES HERE -->

  </div>

  <div class="page-footer">
      {# ===================== SIGNATURES ===================== #}
<div class="sign-row">

  {# Driver #}
  <div class="sign-box">
    <div class="sign-content">
      <div class="sign-head">
        <div class="bi-row">
          <div class="en">Driver Signature</div>
          <div class="ar">توقيع السائق</div>
        </div>
      </div>

      <div class="sign-img">
        {% if doc.driver_signature %}
          <img src="{{ doc.driver_signature | abs_url }}" alt="Driver Signature">
        {% endif %}
      </div>

      <div class="sign-line"></div>
      <div class="sign-name">Name: {{ doc.driver_name_text or doc.driver or "" }}</div>
    </div>
  </div>

  {# Supervisor + Stamp watermark #}
  <div class="sign-box">
    {% if doc.company_stamp %}
      <div class="wm">
        <img src="{{ doc.company_stamp | abs_url }}" alt="Company Stamp Watermark">
      </div>
    {% endif %}

    <div class="sign-content">
      <div class="sign-head">
        <div class="bi-row">
          <!--<div class="en">Supervisor Signature</div>-->
          <!--<div class="ar">توقيع المشرف</div>-->
        </div>
      </div>

      <div class="sign-img">
        {% if doc.supervisor_signature %}
          <img src="{{ doc.supervisor_signature | abs_url }}" alt="Supervisor Signature">
        {% endif %}
      </div>

      <!--<div class="sign-line"></div>-->
      <!--<div class="sign-name">Name: {{ doc.supervisor_name_text or doc.supervisor or "" }}</div>-->
    </div>
  </div>

</div>

{# ===================== FOOTER ===================== #}
{% if phone_no or reg_no %}
  <div class="ftr">
    <div class="ar">
      {% if phone_no %}الهاتف: {{ phone_no }}{% endif %}
      {% if phone_no and reg_no %} | {% endif %}
      {% if reg_no %}رقم التسجيل: {{ reg_no }}{% endif %}
    </div>
    <div>
      {% if phone_no %}Phone: {{ phone_no }}{% endif %}
      {% if phone_no and reg_no %} | {% endif %}
      {% if reg_no %}Reg: {{ reg_no }}{% endif %}
    </div>
  </div>
{% endif %}

    <!-- (LATER STEP) SIGNATURES + FOOTER GO HERE -->

  </div>
</div>
<!-- ===================== PAGE WRAPPER (END) ===================== -->
